Type inference inside a pipeline
```ts
import { BatchStream } from "@ende/streams/batch-stream";
import { assertEquals } from "@ende/assert";

interface User {
  id: string;
}

const users: ReadableStream<User> = ReadableStream.from([
  { id: "a" },
  { id: "b" },
  { id: "c" },
]);

const batches: ReadableStream<User[]> = users.pipeThrough(
  new BatchStream(2),
);

assertEquals(await Array.fromAsync(batches), [
  [{ id: "a" }, { id: "b" }],
  [{ id: "c" }],
]);
```

Buffer input bytes and convert it to a string
```ts
import { Buffer } from "@ende/streams/buffer";
import { toText } from "@ende/streams/to-text";
import { assert } from "@ende/assert";
import { assertEquals } from "@ende/assert";

// Create a new buffer
const buf = new Buffer();
assertEquals(buf.capacity, 0);
assertEquals(buf.length, 0);

// Dummy input stream
const inputStream = ReadableStream.from([
  "hello, ",
  "world",
  "!",
]);

// Pipe the input stream to the buffer
await inputStream.pipeThrough(new TextEncoderStream()).pipeTo(buf.writable);
assert(buf.capacity > 0);
assert(buf.length > 0);

// Convert the buffered bytes to a string
const result = await toText(buf.readable);
assertEquals(result, "hello, world!");
assert(buf.empty());
```

