JSON Lines
```ts
import { TextLineStream } from "@ende/streams/text-line-stream";
import { toTransformStream } from "@ende/streams/to-transform-stream";
import { assertEquals } from "@ende/assert";

const stream = ReadableStream.from([
  '{"name": "Alice", "age": ',
  '30}\n{"name": "Bob", "age"',
  ": 25}\n",
]);

type Person = { name: string; age: number };

// Split the stream by newline and parse each line as a JSON object
const jsonStream = stream.pipeThrough(new TextLineStream())
  .pipeThrough(toTransformStream(async function* (src) {
    for await (const chunk of src) {
      if (chunk.trim().length === 0) {
        continue;
      }
      yield JSON.parse(chunk) as Person;
    }
  }));

assertEquals(
  await Array.fromAsync(jsonStream),
  [{ "name": "Alice", "age": 30 }, { "name": "Bob", "age": 25 }],
);
```

